const rawJson = $input.item.json;

// Check common nesting layers
const payload = rawJson.body || rawJson.data || rawJson;

if (!payload.name || !payload.email || !payload.message) {
  // If it fails, spit out the EXACT payload n8n received so we can see the structure
  throw new Error('REJECTED. I could not find the fields. Here is exactly what n8n received: ' + JSON.stringify(rawJson));
}

return {
  name: payload.name.trim(),
  email: payload.email.toLowerCase().trim(),
  message: payload.message.trim()
};

