parameters.jsCode:
const originalData = $('Clean Input').item.json;
const rawResponse = $input.item.json.choices[0].message.content;
let parsedAi;

try {
  // Attempt to parse the raw string
  parsedAi = JSON.parse(rawResponse);
} catch (error) {
  // If parsing fails, do NOT crash the workflow. 
  // Output a standardized fallback object so Airtable still logs the lead.
  // score: -1 is an intentional sentinel value (not a real score) that trips
  // the "Score >= 7? " IF node's OR-branch (score < 0) so this still alerts.
  return {
    name: originalData.name,
    email: originalData.email,
    message: originalData.message,
    score: -1, 
    summary: "SYSTEM ERROR: LLM returned malformed JSON. Manual qualification required.",
    next_action: "Review immediately."
  };
}

// If it succeeds, return the parsed data, but add fallbacks just in case the LLM skipped a key
return {
  name: originalData.name,
  email: originalData.email,
  message: originalData.message,
  score: parsedAi.score ?? 0,
  summary: parsedAi.summary || "No summary provided.",
  next_action: parsedAi.next_action || "Manual review needed."
};

